    { id=20028, tab=2, tier=2, col=3, name="Anticipation", icon="spell_magic_lesserinvisibilty", maxRank=5, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Increases your Defense skill by 4.", "Increases your Defense skill by 8.", "Increases your Defense skill by 12.", "Increases your Defense skill by 16.", "Increases your Defense skill by 20." }, localized={deDE={name="Vorahnung", tooltip={ "Erhöht Eure Verteidigungsfertigkeit um 4.", "Erhöht Eure Verteidigungsfertigkeit um 8.", "Erhöht Eure Verteidigungsfertigkeit um 12.", "Erhöht Eure Verteidigungsfertigkeit um 16.", "Erhöht Eure Verteidigungsfertigkeit um 20." }}} },
    { id=20029, tab=2, tier=3, col=0, name="Stoicism", icon="spell_holy_stoicism", maxRank=2, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Increases your resistance to Stun effects by an additional 5% and reduces the chance your spells will be dispelled by an additional 15%.", "Increases your resistance to Stun effects by an additional 10% and reduces the chance your spells will be dispelled by an additional 30%." }, localized={deDE={name="Gleichmut", tooltip={ "Erhöht Eure Widerstandschance gegen Betäubungseffekte um zusätzliche 5% und verringert die Chance, dass Eure Zauber gebannt werden, um zusätzliche 15%.", "Erhöht Eure Widerstandschance gegen Betäubungseffekte um zusätzliche 10% und verringert die Chance, dass Eure Zauber gebannt werden, um zusätzliche 30%." }}} },
    { id=20030, tab=2, tier=3, col=1, name="Improved Hammer of Justice", icon="spell_holy_sealofmight", maxRank=3, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Decreases the cooldown of your Hammer of Justice spell by 5 sec.", "Decreases the cooldown of your Hammer of Justice spell by 10 sec.", "Decreases the cooldown of your Hammer of Justice spell by 15 sec." }, localized={deDE={name="Verbesserter Hammer der Gerechtigkeit", tooltip={ "Verringert die Abklingzeit Eures Zaubers 'Hammer der Gerechtigkeit' um 5 Sek.", "Verringert die Abklingzeit Eures Zaubers 'Hammer der Gerechtigkeit' um 10 Sek.", "Verringert die Abklingzeit Eures Zaubers 'Hammer der Gerechtigkeit' um 15 Sek." }}} },
    { id=20031, tab=2, tier=3, col=2, name="Improved Concentration Aura", icon="spell_holy_mindsooth", maxRank=3, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Increases the effect of your Concentration Aura by an additional 5% and reduces the duration of any Silence or Interrupt effect used against an affected group member by 10%. The duration reduction does not stack with any other effects.", "Increases the effect of your Concentration Aura by an additional 10% and reduces the duration of any Silence or Interrupt effect used against an affected group member by 20%. The duration reduction does not stack with any other effects.", "Increases the effect of your Concentration Aura by an additional 15% and reduces the duration of any Silence or Interrupt effect used against an affected group member by 30%. The duration reduction does not stack with any other effects." }, localized={deDE={name="Verbesserte Aura der Konzentration", tooltip={ "Erhöht den Effekt Eurer 'Aura der Konzentration' um zusätzliche 5% und verringert die Dauer aller Stille- und Unterbrechungseffekte gegen betroffene Gruppenmitglieder um 10%. Diese Verringerung der Dauer ist nicht mit anderen Effekten stapelbar.", "Erhöht den Effekt Eurer 'Aura der Konzentration' um zusätzliche 10% und verringert die Dauer aller Stille- und Unterbrechungseffekte gegen betroffene Gruppenmitglieder um 20%. Diese Verringerung der Dauer ist nicht mit anderen Effekten stapelbar.", "Erhöht den Effekt Eurer 'Aura der Konzentration' um zusätzliche 15% und verringert die Dauer aller Stille- und Unterbrechungseffekte gegen betroffene Gruppenmitglieder um 30%. Diese Verringerung der Dauer ist nicht mit anderen Effekten stapelbar." }}} },
    { id=20032, tab=2, tier=4, col=0, name="Spell Warding", icon="spell_holy_improvedresistanceauras", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "All spell damage taken is reduced by 2%.", "All spell damage taken is reduced by 4%." }, localized={deDE={name="Zauberschutz", tooltip={ "Verringert jeglichen erlittenen Zauberschaden um 2%.", "Verringert jeglichen erlittenen Zauberschaden um 4%." }}} },
    { id=20033, tab=2, tier=4, col=1, name="Blessing of Sanctuary", icon="spell_nature_lightningshield", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Places a Blessing on the friendly target, reducing damage dealt from all sources by up to 10 for 10 min. In addition, when the target blocks a melee attack the attacker will take 14 Holy damage. Players may only have one Blessing on them per Paladin at any one time." }, localized={deDE={name="Segen des Refugiums", tooltip={ "Belegt ein befreundetes Ziel mit einem Segen, der den erlittenen Schaden aus allen Quellen 10 Min. lang um bis zu 10 verringert. Wenn das Ziel einen Nahkampfangriff blockt, erleidet der Angreifer zusätzlich 14 Heiligschaden. Spieler können von jedem Paladin immer nur einen Segen gleichzeitig erhalten." }}} },
    { id=20034, tab=2, tier=4, col=2, name="Reckoning", icon="spell_holy_blessingofstrength", maxRank=5, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Gives you a 2% chance after being hit by any damaging attack that the next 4 weapon swings within 8 sec will generate an additional attack.", "Gives you a 4% chance after being hit by any damaging attack that the next 4 weapon swings within 8 sec will generate an additional attack.", "Gives you a 6% chance after being hit by any damaging attack that the next 4 weapon swings within 8 sec will generate an additional attack.", "Gives you a 8% chance after being hit by any damaging attack that the next 4 weapon swings within 8 sec will generate an additional attack.", "Gives you a 10% chance after being hit by any damaging attack that the next 4 weapon swings within 8 sec will generate an additional attack." }, grant={ [1]=20177, [2]=20179, [3]=20181, [4]=20180, [5]=20182 }, localized={deDE={name="Abrechnung", tooltip={ "Gewährt Euch nach einem erlittenen Schaden verursachenden Angriff eine Chance von 2%, dass Eure nächsten 4 Waffenschläge innerhalb von 8 Sek. jeweils einen zusätzlichen Angriff erzeugen.", "Gewährt Euch nach einem erlittenen Schaden verursachenden Angriff eine Chance von 4%, dass Eure nächsten 4 Waffenschläge innerhalb von 8 Sek. jeweils einen zusätzlichen Angriff erzeugen.", "Gewährt Euch nach einem erlittenen Schaden verursachenden Angriff eine Chance von 6%, dass Eure nächsten 4 Waffenschläge innerhalb von 8 Sek. jeweils einen zusätzlichen Angriff erzeugen.", "Gewährt Euch nach einem erlittenen Schaden verursachenden Angriff eine Chance von 8%, dass Eure nächsten 4 Waffenschläge innerhalb von 8 Sek. jeweils einen zusätzlichen Angriff erzeugen.", "Gewährt Euch nach einem erlittenen Schaden verursachenden Angriff eine Chance von 10%, dass Eure nächsten 4 Waffenschläge innerhalb von 8 Sek. jeweils einen zusätzlichen Angriff erzeugen." }}} },
    { id=20035, tab=2, tier=5, col=0, name="Sacred Duty", icon="spell_holy_divineintervention", maxRank=2, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Increases your total Stamina by 3%, reduces the cooldown of your Divine Shield spell by 30 sec and reduces the attack speed penalty by 50%.", "Increases your total Stamina by 6%, reduces the cooldown of your Divine Shield spell by 60 sec and reduces the attack speed penalty by 100%." }, localized={deDE={name="Heilige Pflicht", tooltip={ "Erhöht Eure gesamte Ausdauer um 3%, verringert die Abklingzeit Eures Zaubers 'Gottesschild' um 30 Sek. und verringert dessen Angriffstempomalus um 50%.", "Erhöht Eure gesamte Ausdauer um 6%, verringert die Abklingzeit Eures Zaubers 'Gottesschild' um 60 Sek. und verringert dessen Angriffstempomalus um 100%." }}} },
    { id=20036, tab=2, tier=5, col=2, name="One-Handed Weapon Specialization", icon="inv_sword_20", maxRank=5, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Increases all damage you deal when a one-handed melee weapon is equipped by 1%.", "Increases all damage you deal when a one-handed melee weapon is equipped by 2%.", "Increases all damage you deal when a one-handed melee weapon is equipped by 3%.", "Increases all damage you deal when a one-handed melee weapon is equipped by 4%.", "Increases all damage you deal when a one-handed melee weapon is equipped by 5%." }, localized={deDE={name="Einhandwaffen-Spezialisierung", tooltip={ "Erhöht jeglichen von Euch verursachten Schaden um 1%, wenn eine einhändige Nahkampfwaffe angelegt ist.", "Erhöht jeglichen von Euch verursachten Schaden um 2%, wenn eine einhändige Nahkampfwaffe angelegt ist.", "Erhöht jeglichen von Euch verursachten Schaden um 3%, wenn eine einhändige Nahkampfwaffe angelegt ist.", "Erhöht jeglichen von Euch verursachten Schaden um 4%, wenn eine einhändige Nahkampfwaffe angelegt ist.", "Erhöht jeglichen von Euch verursachten Schaden um 5%, wenn eine einhändige Nahkampfwaffe angelegt ist." }}} },
    { id=20037, tab=2, tier=6, col=0, name="Improved Holy Shield", icon="spell_holy_blessingofprotection", maxRank=2, prereqTalent=20038, prereqPoints=30, wired=true, tooltip={ "Increases damage caused by your Holy Shield by 10% and increases the number of charges of your Holy Shield by 2.", "Increases damage caused by your Holy Shield by 20% and increases the number of charges of your Holy Shield by 4." }, localized={deDE={name="Verbesserter Heiliger Schild", tooltip={ "Erhöht den Schaden Eures 'Heiligen Schilds' um 10% und die Anzahl seiner Aufladungen um 2.", "Erhöht den Schaden Eures 'Heiligen Schilds' um 20% und die Anzahl seiner Aufladungen um 4." }}} },
    { id=20038, tab=2, tier=6, col=1, name="Holy Shield", icon="spell_holy_blessingofprotection", maxRank=1, prereqTalent=20033, prereqPoints=30, wired=true, tooltip={ "Increases chance to block by 30% for 10 sec and deals 59 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 35% additional threat. Each block expends a charge. 4 charges." }, grant={ [1]=946095 }, localized={deDE={name="Heiliger Schild", tooltip={ "Erhöht Eure Blockchance 10 Sek. lang um 30% und verursacht bei jedem während der Wirkungsdauer geblockten Angriff 59 Heiligschaden. Der Schaden von 'Heiliger Schild' erzeugt 35% zusätzliche Bedrohung. Jeder geblockte Angriff verbraucht eine Aufladung. 4 Aufladungen." }}} },
    { id=20039, tab=2, tier=6, col=2, name="Ardent Defender", icon="spell_holy_ardentdefender", maxRank=5, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "When you have less than 35% health, all damage taken is reduced by 6%.", "When you have less than 35% health, all damage taken is reduced by 12%.", "When you have less than 35% health, all damage taken is reduced by 18%.", "When you have less than 35% health, all damage taken is reduced by 24%.", "When you have less than 35% health, all damage taken is reduced by 30%." }, localized={deDE={name="Unermüdlicher Verteidiger", tooltip={ "Verringert jeglichen erlittenen Schaden um 6%, wenn Ihr weniger als 35% Gesundheit habt.", "Verringert jeglichen erlittenen Schaden um 12%, wenn Ihr weniger als 35% Gesundheit habt.", "Verringert jeglichen erlittenen Schaden um 18%, wenn Ihr weniger als 35% Gesundheit habt.", "Verringert jeglichen erlittenen Schaden um 24%, wenn Ihr weniger als 35% Gesundheit habt.", "Verringert jeglichen erlittenen Schaden um 30%, wenn Ihr weniger als 35% Gesundheit habt." }}} },
    { id=20040, tab=2, tier=7, col=2, name="Combat Expertise", icon="spell_holy_weaponmastery", maxRank=5, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "Increases your expertise by 1 and your total Stamina by 2%.", "Increases your expertise by 2 and your total Stamina by 4%.", "Increases your expertise by 3 and your total Stamina by 6%.", "Increases your expertise by 4 and your total Stamina by 8%.", "Increases your expertise by 5 and your total Stamina by 10%." }, localized={deDE={name="Kampfexperte", tooltip={ "Erhöht Eure Waffenkunde um 1 und Eure gesamte Ausdauer um 2%.", "Erhöht Eure Waffenkunde um 2 und Eure gesamte Ausdauer um 4%.", "Erhöht Eure Waffenkunde um 3 und Eure gesamte Ausdauer um 6%.", "Erhöht Eure Waffenkunde um 4 und Eure gesamte Ausdauer um 8%.", "Erhöht Eure Waffenkunde um 5 und Eure gesamte Ausdauer um 10%." }}} },
    { id=20041, tab=2, tier=8, col=1, name="Avenger's Shield", icon="spell_holy_avengersshield", maxRank=1, prereqTalent=20038, prereqPoints=40, wired=true, tooltip={ "Hurls a holy shield at the enemy, dealing 270 to 330 Holy damage, Dazing them and then jumping to additional nearby enemies. Affects 3 total targets. Lasts 6 sec." }, grant={ [1]=946102 }, localized={deDE={name="Schild des Rächers", tooltip={ "Schleudert einen heiligen Schild auf den Feind, der 270 bis 330 Heiligschaden verursacht, ihn benommen macht und anschließend auf weitere Feinde in der Nähe überspringt. Betrifft insgesamt 3 Ziele. Hält 6 Sek. lang an." }}} },
    { id=20042, tab=3, tier=0, col=1, name="Improved Blessing of Might", icon="spell_holy_fistofjustice", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Increases the attack power bonus of your Blessing of Might by 4%.", "Increases the attack power bonus of your Blessing of Might by 8%.", "Increases the attack power bonus of your Blessing of Might by 12%.", "Increases the attack power bonus of your Blessing of Might by 16%.", "Increases the attack power bonus of your Blessing of Might by 20%." }, localized={deDE={name="Verbesserter Segen der Macht", tooltip={ "Erhöht den Angriffskraftbonus Eures 'Segens der Macht' um 4%.", "Erhöht den Angriffskraftbonus Eures 'Segens der Macht' um 8%.", "Erhöht den Angriffskraftbonus Eures 'Segens der Macht' um 12%.", "Erhöht den Angriffskraftbonus Eures 'Segens der Macht' um 16%.", "Erhöht den Angriffskraftbonus Eures 'Segens der Macht' um 20%." }}} },
    { id=20043, tab=3, tier=0, col=2, name="Benediction", icon="spell_frost_windwalkon", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Reduces the mana cost of your Judgement and Seal spells by 3%.", "Reduces the mana cost of your Judgement and Seal spells by 6%.", "Reduces the mana cost of your Judgement and Seal spells by 9%.", "Reduces the mana cost of your Judgement and Seal spells by 12%.", "Reduces the mana cost of your Judgement and Seal spells by 15%." }, localized={deDE={name="Segnung", tooltip={ "Verringert die Manakosten Eurer Richturteil- und Siegelzauber um 3%.", "Verringert die Manakosten Eurer Richturteil- und Siegelzauber um 6%.", "Verringert die Manakosten Eurer Richturteil- und Siegelzauber um 9%.", "Verringert die Manakosten Eurer Richturteil- und Siegelzauber um 12%.", "Verringert die Manakosten Eurer Richturteil- und Siegelzauber um 15%." }}} },
    { id=20044, tab=3, tier=1, col=0, name="Improved Judgement", icon="spell_holy_righteousfury", maxRank=2, prereqTalent=0, prereqPoints=5, wired=true, tooltip={ "Decreases the cooldown of your Judgement spell by 1 sec.", "Decreases the cooldown of your Judgement spell by 2 sec." }, localized={deDE={name="Verbessertes Richturteil", tooltip={ "Verringert die Abklingzeit Eures Zaubers 'Richturteil' um 1 Sek.", "Verringert die Abklingzeit Eures Zaubers 'Richturteil' um 2 Sek." }}} },
    { id=20045, tab=3, tier=1, col=1, name="Improved Seal of the Crusader", icon="spell_holy_holysmite", maxRank=3, prereqTalent=0, prereqPoints=5, wired=true, tooltip={ "In addition to the normal effect, your Judgement of the Crusader spell will also increase the critical strike chance of all attacks made against that target by an additional 1%.", "In addition to the normal effect, your Judgement of the Crusader spell will also increase the critical strike chance of all attacks made against that target by an additional 2%.", "In addition to the normal effect, your Judgement of the Crusader spell will also increase the critical strike chance of all attacks made against that target by an additional 3%." }, localized={deDE={name="Verbessertes Siegel des Kreuzfahrers", tooltip={ "Zusätzlich zum normalen Effekt erhöht Euer Zauber 'Richturteil des Kreuzfahrers' die kritische Trefferchance aller Angriffe gegen dieses Ziel um zusätzliche 1%.", "Zusätzlich zum normalen Effekt erhöht Euer Zauber 'Richturteil des Kreuzfahrers' die kritische Trefferchance aller Angriffe gegen dieses Ziel um zusätzliche 2%.", "Zusätzlich zum normalen Effekt erhöht Euer Zauber 'Richturteil des Kreuzfahrers' die kritische Trefferchance aller Angriffe gegen dieses Ziel um zusätzliche 3%." }}} },
    { id=20046, tab=3, tier=1, col=2, name="Deflection", icon="ability_parry", maxRank=5, prereqTalent=0, prereqPoints=5, wired=true, tooltip={ "Increases your Parry chance by 1%.", "Increases your Parry chance by 2%.", "Increases your Parry chance by 3%.", "Increases your Parry chance by 4%.", "Increases your Parry chance by 5%." }, localized={deDE={name="Abwehr", tooltip={ "Erhöht Eure Parierchance um 1%.", "Erhöht Eure Parierchance um 2%.", "Erhöht Eure Parierchance um 3%.", "Erhöht Eure Parierchance um 4%.", "Erhöht Eure Parierchance um 5%." }}} },
    { id=20047, tab=3, tier=2, col=0, name="Vindication", icon="spell_holy_vindication", maxRank=3, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Gives the Paladin's damaging melee attacks a chance to reduce the target's attributes by 5% for 15 sec.", "Gives the Paladin's damaging melee attacks a chance to reduce the target's attributes by 10% for 15 sec.", "Gives the Paladin's damaging melee attacks a chance to reduce the target's attributes by 15% for 15 sec." }, localized={deDE={name="Recht und Ordnung", tooltip={ "Die Schaden verursachenden Nahkampfangriffe des Paladins haben eine Chance, die Attribute des Ziels 15 Sek. lang um 5% zu verringern.", "Die Schaden verursachenden Nahkampfangriffe des Paladins haben eine Chance, die Attribute des Ziels 15 Sek. lang um 10% zu verringern.", "Die Schaden verursachenden Nahkampfangriffe des Paladins haben eine Chance, die Attribute des Ziels 15 Sek. lang um 15% zu verringern." }}} },
    { id=20048, tab=3, tier=2, col=1, name="Conviction", icon="spell_holy_retributionaura", maxRank=5, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Increases your chance to get a critical strike with melee weapons by 1%.", "Increases your chance to get a critical strike with melee weapons by 2%.", "Increases your chance to get a critical strike with melee weapons by 3%.", "Increases your chance to get a critical strike with melee weapons by 4%.", "Increases your chance to get a critical strike with melee weapons by 5%." }, localized={deDE={name="Überzeugung", tooltip={ "Erhöht Eure Chance, mit Nahkampfwaffen einen kritischen Treffer zu erzielen, um 1%.", "Erhöht Eure Chance, mit Nahkampfwaffen einen kritischen Treffer zu erzielen, um 2%.", "Erhöht Eure Chance, mit Nahkampfwaffen einen kritischen Treffer zu erzielen, um 3%.", "Erhöht Eure Chance, mit Nahkampfwaffen einen kritischen Treffer zu erzielen, um 4%.", "Erhöht Eure Chance, mit Nahkampfwaffen einen kritischen Treffer zu erzielen, um 5%." }}} },
    { id=20049, tab=3, tier=2, col=2, name="Seal of Command", icon="ability_warrior_innerrage", maxRank=1, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage. Only one Seal can be active on the Paladin at any one time. Lasts 30 sec. Unleashing this Seal's energy will judge an enemy, instantly causing 68 to 73 Holy damage, 137 to 146 if the target is stunned or incapacitated." }, grant={ [1]=946027 }, localized={deDE={name="Siegel des Befehls", tooltip={ "Gewährt dem Paladin eine Chance, zusätzlichen Heiligschaden in Höhe von 70% des normalen Waffenschadens zu verursachen. Auf dem Paladin kann immer nur ein Siegel gleichzeitig aktiv sein. Hält 30 Sek. lang an. Das Entfesseln der Energie dieses Siegels richtet einen Feind und verursacht sofort 68 bis 73 Heiligschaden oder 137 bis 146, wenn das Ziel betäubt oder handlungsunfähig ist." }}} },
    { id=20050, tab=3, tier=2, col=3, name="Pursuit of Justice", icon="spell_holy_persuitofjustice", maxRank=3, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Reduces the chance you'll be hit by spells by 1% and increases movement and mounted movement speed by 5%. This does not stack with other movement speed increasing effects.", "Reduces the chance you'll be hit by spells by 2% and increases movement and mounted movement speed by 10%. This does not stack with other movement speed increasing effects.", "Reduces the chance you'll be hit by spells by 3% and increases movement and mounted movement speed by 15%. This does not stack with other movement speed increasing effects." }, localized={deDE={name="Streben nach Gerechtigkeit", tooltip={ "Verringert die Chance, dass Ihr von Zaubern getroffen werdet, um 1% und erhöht Eure Bewegungsgeschwindigkeit sowie Eure Reitgeschwindigkeit um 5%. Nicht mit anderen Effekten stapelbar, welche die Bewegungsgeschwindigkeit erhöhen.", "Verringert die Chance, dass Ihr von Zaubern getroffen werdet, um 2% und erhöht Eure Bewegungsgeschwindigkeit sowie Eure Reitgeschwindigkeit um 10%. Nicht mit anderen Effekten stapelbar, welche die Bewegungsgeschwindigkeit erhöhen.", "Verringert die Chance, dass Ihr von Zaubern getroffen werdet, um 3% und erhöht Eure Bewegungsgeschwindigkeit sowie Eure Reitgeschwindigkeit um 15%. Nicht mit anderen Effekten stapelbar, welche die Bewegungsgeschwindigkeit erhöhen." }}} },
    { id=20051, tab=3, tier=3, col=0, name="Eye for an Eye", icon="spell_holy_eyeforaneye", maxRank=2, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "All spell criticals against you cause 15% of the damage taken to the caster as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.", "All spell criticals against you cause 30% of the damage taken to the caster as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health." }, localized={deDE={name="Auge um Auge", tooltip={ "Alle kritischen Zaubertreffer gegen Euch fügen dem Zaubernden ebenfalls 15% des erlittenen Schadens zu. Der durch 'Auge um Auge' verursachte Schaden kann 50% der gesamten Gesundheit des Paladins nicht übersteigen.", "Alle kritischen Zaubertreffer gegen Euch fügen dem Zaubernden ebenfalls 30% des erlittenen Schadens zu. Der durch 'Auge um Auge' verursachte Schaden kann 50% der gesamten Gesundheit des Paladins nicht übersteigen." }}} },
    { id=20052, tab=3, tier=3, col=2, name="Improved Retribution Aura", icon="spell_holy_auraoflight", maxRank=2, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Increases the damage done by your Retribution Aura by 25%.", "Increases the damage done by your Retribution Aura by 50%." }, localized={deDE={name="Verbesserte Aura der Vergeltung", tooltip={ "Erhöht den Schaden Eurer 'Aura der Vergeltung' um 25%.", "Erhöht den Schaden Eurer 'Aura der Vergeltung' um 50%." }}} },
    { id=20053, tab=3, tier=3, col=3, name="Crusade", icon="spell_holy_crusade", maxRank=3, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Increases all damage caused against Humanoids, Demons, Undead and Elementals by 1%.", "Increases all damage caused against Humanoids, Demons, Undead and Elementals by 2%.", "Increases all damage caused against Humanoids, Demons, Undead and Elementals by 3%." }, localized={deDE={name="Kreuzzug", tooltip={ "Erhöht jeglichen verursachten Schaden gegen Humanoide, Dämonen, Untote und Elementare um 1%.", "Erhöht jeglichen verursachten Schaden gegen Humanoide, Dämonen, Untote und Elementare um 2%.", "Erhöht jeglichen verursachten Schaden gegen Humanoide, Dämonen, Untote und Elementare um 3%." }}} },
    { id=20054, tab=3, tier=4, col=0, name="Two-Handed Weapon Specialization", icon="inv_hammer_04", maxRank=3, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases the damage you deal with two-handed melee weapons by 2%.", "Increases the damage you deal with two-handed melee weapons by 4%.", "Increases the damage you deal with two-handed melee weapons by 6%." }, localized={deDE={name="Zweihandwaffen-Spezialisierung", tooltip={ "Erhöht den Schaden, den Ihr mit zweihändigen Nahkampfwaffen verursacht, um 2%.", "Erhöht den Schaden, den Ihr mit zweihändigen Nahkampfwaffen verursacht, um 4%.", "Erhöht den Schaden, den Ihr mit zweihändigen Nahkampfwaffen verursacht, um 6%." }}} },
    { id=20055, tab=3, tier=4, col=2, name="Sanctity Aura", icon="spell_holy_mindvision", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases Holy damage done by party members within 30 yards by 10%. Players may only have one Aura on them per Paladin at any one time." }, localized={deDE={name="Aura der Heiligkeit", tooltip={ "Erhöht den verursachten Heiligschaden von Gruppenmitgliedern im Umkreis von 30 Metern um 10%. Spieler können von jedem Paladin immer nur eine Aura gleichzeitig erhalten." }}} },
    { id=20056, tab=3, tier=4, col=3, name="Improved Sanctity Aura", icon="spell_holy_mindvision", maxRank=2, prereqTalent=20055, prereqPoints=20, wired=true, tooltip={ "The amount of damage caused by targets affected by Sanctity Aura is increased by 1%.", "The amount of damage caused by targets affected by Sanctity Aura is increased by 2%." }, localized={deDE={name="Verbesserte Aura der Heiligkeit", tooltip={ "Erhöht den Schaden, den von 'Aura der Heiligkeit' betroffene Ziele verursachen, um 1%.", "Erhöht den Schaden, den von 'Aura der Heiligkeit' betroffene Ziele verursachen, um 2%." }}} },
    { id=20057, tab=3, tier=5, col=1, name="Vengeance", icon="ability_racial_avatar", maxRank=5, prereqTalent=20048, prereqPoints=25, wired=true, tooltip={ "Gives you a 1% bonus to Physical and Holy damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability. This effect stacks up to 3 times.", "Gives you a 2% bonus to Physical and Holy damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability. This effect stacks up to 3 times.", "Gives you a 3% bonus to Physical and Holy damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability. This effect stacks up to 3 times.", "Gives you a 4% bonus to Physical and Holy damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability. This effect stacks up to 3 times.", "Gives you a 5% bonus to Physical and Holy damage you deal for 30 sec after dealing a critical strike from a weapon swing, spell, or ability. This effect stacks up to 3 times." }, localized={deDE={name="Rache", tooltip={ "Gewährt Euch nach einem kritischen Treffer mit einem Waffenschlag, Zauber oder einer Fähigkeit 30 Sek. lang einen Bonus von 1% auf Euren verursachten körperlichen Schaden und Heiligschaden. Dieser Effekt ist bis zu 3-mal stapelbar.", "Gewährt Euch nach einem kritischen Treffer mit einem Waffenschlag, Zauber oder einer Fähigkeit 30 Sek. lang einen Bonus von 2% auf Euren verursachten körperlichen Schaden und Heiligschaden. Dieser Effekt ist bis zu 3-mal stapelbar.", "Gewährt Euch nach einem kritischen Treffer mit einem Waffenschlag, Zauber oder einer Fähigkeit 30 Sek. lang einen Bonus von 3% auf Euren verursachten körperlichen Schaden und Heiligschaden. Dieser Effekt ist bis zu 3-mal stapelbar.", "Gewährt Euch nach einem kritischen Treffer mit einem Waffenschlag, Zauber oder einer Fähigkeit 30 Sek. lang einen Bonus von 4% auf Euren verursachten körperlichen Schaden und Heiligschaden. Dieser Effekt ist bis zu 3-mal stapelbar.", "Gewährt Euch nach einem kritischen Treffer mit einem Waffenschlag, Zauber oder einer Fähigkeit 30 Sek. lang einen Bonus von 5% auf Euren verursachten körperlichen Schaden und Heiligschaden. Dieser Effekt ist bis zu 3-mal stapelbar." }}} },
    { id=20058, tab=3, tier=5, col=2, name="Sanctified Judgement", icon="spell_holy_righteousfury", maxRank=3, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Gives your Judgement spell a 33% chance to return 80% of the mana cost of the judged seal.", "Gives your Judgement spell a 66% chance to return 80% of the mana cost of the judged seal.", "Gives your Judgement spell a 100% chance to return 80% of the mana cost of the judged seal." }, localized={deDE={name="Geheiligtes Richturteil", tooltip={ "Gewährt Eurem Zauber 'Richturteil' eine Chance von 33%, 80% der Manakosten des durch Richturteil verbrauchten Siegels zurückzuerhalten.", "Gewährt Eurem Zauber 'Richturteil' eine Chance von 66%, 80% der Manakosten des durch Richturteil verbrauchten Siegels zurückzuerhalten.", "Gewährt Eurem Zauber 'Richturteil' eine Chance von 100%, 80% der Manakosten des durch Richturteil verbrauchten Siegels zurückzuerhalten." }}} },
    { id=20059, tab=3, tier=6, col=0, name="Sanctified Seals", icon="spell_holy_holysmite", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Increases your chance to critically hit with all spells and melee attacks by 1% and reduces the chance your Seals will be dispelled by 33%.", "Increases your chance to critically hit with all spells and melee attacks by 2% and reduces the chance your Seals will be dispelled by 66%.", "Increases your chance to critically hit with all spells and melee attacks by 3% and reduces the chance your Seals will be dispelled by 100%." }, localized={deDE={name="Geheiligte Siegel", tooltip={ "Erhöht Eure kritische Trefferchance mit allen Zaubern und Nahkampfangriffen um 1% und verringert die Chance, dass Eure Siegel gebannt werden, um 33%.", "Erhöht Eure kritische Trefferchance mit allen Zaubern und Nahkampfangriffen um 2% und verringert die Chance, dass Eure Siegel gebannt werden, um 66%.", "Erhöht Eure kritische Trefferchance mit allen Zaubern und Nahkampfangriffen um 3% und verringert die Chance, dass Eure Siegel gebannt werden, um 100%." }}} },
    { id=20060, tab=3, tier=6, col=1, name="Repentance", icon="spell_holy_prayerofhealing", maxRank=1, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec. Any damage caused will awaken the target. Only works against Humanoids." }, grant={ [1]=946146 }, localized={deDE={name="Buße", tooltip={ "Versetzt das feindliche Ziel in einen Zustand der Meditation und macht es bis zu 6 Sek. lang handlungsunfähig. Jeglicher zugefügte Schaden weckt das Ziel auf. Wirkt nur auf Humanoide." }}} },
    { id=20061, tab=3, tier=6, col=2, name="Divine Purpose", icon="spell_holy_divinepurpose", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Melee and ranged critical strikes against you cause 4% less damage.", "Melee and ranged critical strikes against you cause 7% less damage.", "Melee and ranged critical strikes against you cause 10% less damage." }, localized={deDE={name="Göttliche Bestimmung", tooltip={ "Kritische Nahkampf- und Fernkampftreffer gegen Euch verursachen 4% weniger Schaden.", "Kritische Nahkampf- und Fernkampftreffer gegen Euch verursachen 7% weniger Schaden.", "Kritische Nahkampf- und Fernkampftreffer gegen Euch verursachen 10% weniger Schaden." }}} },
    { id=20062, tab=3, tier=7, col=1, name="Fanaticism", icon="spell_holy_fanaticism", maxRank=5, prereqTalent=20060, prereqPoints=35, wired=true, tooltip={ "Increases the critical strike chance of all Judgements capable of a critical hit by 3% and reduces threat caused by all actions by 6% except when under the effects of Righteous Fury.", "Increases the critical strike chance of all Judgements capable of a critical hit by 6% and reduces threat caused by all actions by 12% except when under the effects of Righteous Fury.", "Increases the critical strike chance of all Judgements capable of a critical hit by 9% and reduces threat caused by all actions by 18% except when under the effects of Righteous Fury.", "Increases the critical strike chance of all Judgements capable of a critical hit by 12% and reduces threat caused by all actions by 24% except when under the effects of Righteous Fury.", "Increases the critical strike chance of all Judgements capable of a critical hit by 15% and reduces threat caused by all actions by 30% except when under the effects of Righteous Fury." }, localized={deDE={name="Fanatismus", tooltip={ "Erhöht die kritische Trefferchance aller Richturteile, die kritisch treffen können, um 3% und verringert die durch alle Aktionen erzeugte Bedrohung um 6%, außer wenn 'Zorn der Gerechtigkeit' aktiv ist.", "Erhöht die kritische Trefferchance aller Richturteile, die kritisch treffen können, um 6% und verringert die durch alle Aktionen erzeugte Bedrohung um 12%, außer wenn 'Zorn der Gerechtigkeit' aktiv ist.", "Erhöht die kritische Trefferchance aller Richturteile, die kritisch treffen können, um 9% und verringert die durch alle Aktionen erzeugte Bedrohung um 18%, außer wenn 'Zorn der Gerechtigkeit' aktiv ist.", "Erhöht die kritische Trefferchance aller Richturteile, die kritisch treffen können, um 12% und verringert die durch alle Aktionen erzeugte Bedrohung um 24%, außer wenn 'Zorn der Gerechtigkeit' aktiv ist.", "Erhöht die kritische Trefferchance aller Richturteile, die kritisch treffen können, um 15% und verringert die durch alle Aktionen erzeugte Bedrohung um 30%, außer wenn 'Zorn der Gerechtigkeit' aktiv ist." }}} },
